Definition KP (A : AS) (X : word -> Prop) (m m' : word -> option byte) : Prop :=
  forall (q : word) k i, live A q = Some k -> ~ X q -> (0 <= i < k)%Z -> m' (at_ q i) = m (at_ q i).

