  (* [comment removed for export] *)
  Definition FR4d (m : word -> option byte) (s : Z) (ret : word) (regs : bvmap 5 word) (cmd : Z) : word -> option byte :=
    wbytes (wbytes (wbytes (wbytes m
       (Z_to_bv 64 (s - 8)) (word_to_le_bytes 8 ret))
       (Z_to_bv 64 (s - 16)) (word_to_le_bytes 8 (getr regs 8)))
       (Z_to_bv 64 (s - 24)) (word_to_le_bytes 8 (getr regs 9)))
       (Z_to_bv 64 (s - 32)) (word_to_le_bytes 8 (Z_to_bv 64 cmd)).

  Lemma cells3_FR4d : forall m s ret regs cmd, (48 <= s)%Z -> (s < 2 ^ 64)%Z ->
    cells3 (FR4d m s ret regs cmd) s ret (getr regs 8) (getr regs 9).
Proof.
