(* [comment removed for export] *)
Definition Xcm (pixd cmd arrd : Z) (q : word) : Prop :=
  q = Z_to_bv 64 pixd \/ (cmd <> 0%Z /\ (q = Z_to_bv 64 cmd \/ q = Z_to_bv 64 arrd)).

(* [comment removed for export] *)
Definition pcg_live (C : lctx) (A A' : AS) (m' : word -> option byte) (cms : Z) (cvs : cmapv) (cmd arrd cd' : Z) (cvd' : cmapv) : Prop :=
  (cms = 0%Z /\ cd' = 0%Z /\
     (forall q : word, (cmd <> 0%Z -> q <> Z_to_bv 64 cmd /\ q <> Z_to_bv 64 arrd) -> live A' q = live A q) /\
     (cmd <> 0%Z -> live A' (Z_to_bv 64 cmd) = None /\ live A' (Z_to_bv 64 arrd) = None))
  \/ (cms <> 0%Z /\ cd' <> 0%Z /\ CMAPat m' cd' cvd' /\ cmap_ok cvd' /\
      c_d cvd' = c_d cvs /\ c_nalloc cvd' = c_nalloc cvs /\ c_n cvd' = c_n cvs /\
      live A' (Z_to_bv 64 cd') = Some 24%Z /\ live A' (Z_to_bv 64 (c_arr cvd')) = Some (4 * c_nalloc cvd')%Z /\
      live (c_A0 C) (Z_to_bv 64 cd') = None /\ live (c_A0 C) (Z_to_bv 64 (c_arr cvd')) = None /\
      (forall (q : word) k, live A q = Some k -> (cmd <> 0%Z -> q <> Z_to_bv 64 cmd /\ q <> Z_to_bv 64 arrd) ->
                            q <> Z_to_bv 64 cd' /\ q <> Z_to_bv 64 (c_arr cvd')) /\
      (forall q : word, (cmd <> 0%Z -> q <> Z_to_bv 64 cmd /\ q <> Z_to_bv 64 arrd) ->
                        q <> Z_to_bv 64 cd' -> q <> Z_to_bv 64 (c_arr cvd') -> live A' q = live A q) /\
      (forall q : word, cmd <> 0%Z -> (q = Z_to_bv 64 cmd \/ q = Z_to_bv 64 arrd) ->
                        q <> Z_to_bv 64 cd' -> q <> Z_to_bv 64 (c_arr cvd') -> live A' q = None)).

(* [comment removed for export] *)
Lemma pcg_live_of : forall C A A1 A2 (m2 : word -> option byte) (cms : Z) (cvs : cmapv) (cmd arrd cd : Z),
  (forall q : word, (cmd <> 0%Z -> q <> Z_to_bv 64 cmd /\ q <> Z_to_bv 64 arrd) -> live A1 q = live A q) ->
  (cmd <> 0%Z -> live A1 (Z_to_bv 64 cmd) = None /\ live A1 (Z_to_bv 64 arrd) = None) ->
  ( (cms = 0%Z /\ cd = 0%Z /\ forall q, live A2 q = live A1 q) \/ (cms <> 0%Z /\ exists ad, cmap_copy C A1 A2 m2 cd ad cvs) ) ->
  exists cvd', pcg_live C A A2 m2 cms cvs cmd arrd cd cvd' /\
    (forall (q : word) k, live A q = Some k -> (cmd <> 0%Z -> q <> Z_to_bv 64 cmd /\ q <> Z_to_bv 64 arrd) -> live A2 q = Some k).
